USE [MuOnline97]
GO

SET NOCOUNT ON; -- Oculta contadores de linhas afetadas para execucao rapida

-- Garante que a coluna Inventory da tabela Character suporte o tamanho do inventario
IF EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = 'Character' AND COLUMN_NAME = 'Inventory' AND CHARACTER_MAXIMUM_LENGTH < 1728)
BEGIN
    ALTER TABLE [dbo].[Character] ALTER COLUMN [Inventory] VARBINARY(1728);
END
GO

-- Definicao das cadeias de bytes hexadecimais do inventario equipado para cada classe
