-- Tabela temporaria em memoria para exibir o relatorio detalhado final
DECLARE @ContasCriadas TABLE (
    Num INT,               -- Numero da conta (1 a 50)
    Login VARCHAR(10),     -- Nome do usuario (memb___id)
    Senha VARCHAR(10),     -- Senha de acesso (123456)
    NickName VARCHAR(10),  -- Nome do personagem criado
    Classe VARCHAR(20),    -- Nome da classe (Soul Master, Blade Knight, etc.)
    SetEquipado VARCHAR(80)-- Descricao dos itens equipados no personagem
);

