-- Declaracao das variaveis de controle da iteracao
DECLARE @i INT = 1;                              -- Contador do laco WHILE (inicia em 1)
DECLARE @AccountID VARCHAR(10);                  -- Armazena o login gerado (ex: test01)
DECLARE @CharName VARCHAR(10);                   -- Armazena o nickname do personagem
DECLARE @Password VARCHAR(10) = '123456';        -- Senha padrao para todas as contas
DECLARE @Class TINYINT;                          -- Codigo numerico da Classe (1=SM, 17=BK, 33=ME, 48=MG)
DECLARE @ClassName VARCHAR(20);                  -- Nome legivel da Classe
DECLARE @SetDesc VARCHAR(80);                    -- Descricao do kit de itens da classe
DECLARE @Inventory VARBINARY(1728);              -- Buffer binario do inventario equipado

-- Inicio do laco para criar as 50 contas e personagens
WHILE @i <= 50
BEGIN
    -- Formata o nome de login limpo com 2 digitos (test01 ate test50)
    SET @AccountID = 'test' + RIGHT('0' + CAST(@i AS VARCHAR(2)), 2);
    
    -- Seleciona o nickname correspondente na tabela auxiliar de nicks
    SELECT @CharName = Nick FROM @Nicks WHERE Id = @i;
    IF @CharName IS NULL SET @CharName = 'Player' + RIGHT('0' + CAST(@i AS VARCHAR(2)), 2);

    -- ------------------------------------------------------------------------
    -- LOGICA DE ALTERNANCIA DE CLASSES LEVEL 2 E INVENTARIOS HASH
    -- Utiliza o operador de resto da divisao (@i % 4) para alternar entre as 4 classes
    -- ------------------------------------------------------------------------
    IF (@i % 4 = 1) BEGIN
        SET @Class = 17;                                                               -- 17 = Blade Knight (Classe Lvl 2)
        SET @ClassName = 'Blade Knight';                                               -- Nome de exibicao da classe
        SET @SetDesc = 'Knight Blade + Chaos Shield + Dragon Set +11 (Luck+Opt28+Full)'; -- Descricao
        SET @Inventory = @DK_INV;                                                      -- Aloca os bytes hexadecimais do BK
    END ELSE IF (@i % 4 = 2) BEGIN
        SET @Class = 1;                                                                -- 1 = Soul Master (Classe Lvl 2)
        SET @ClassName = 'Soul Master';                                                -- Nome de exibicao da classe
        SET @SetDesc = 'Legendary Staff + Shield + Legendary Set +11 (Luck+Opt28+Full)';-- Descricao
        SET @Inventory = @DW_INV;                                                      -- Aloca os bytes hexadecimais do SM
    END ELSE IF (@i % 4 = 3) BEGIN
        SET @Class = 33;                                                               -- 33 = Muse Elf (Classe Lvl 2)
        SET @ClassName = 'Muse Elf';                                                   -- Nome de exibicao da classe
        SET @SetDesc = 'Celestial Bow + Divine Set +11 (Luck+Opt28+Full)';             -- Descricao
        SET @Inventory = @ELF_INV;                                                     -- Aloca os bytes hexadecimais da ME
    END ELSE BEGIN
        SET @Class = 48;                                                               -- 48 = Magic Gladiator (MG)
        SET @ClassName = 'Magic Gladiator';                                            -- Nome de exibicao da classe
        SET @SetDesc = 'Absolute Staff Archangel + Legendary Shield + Hurricane Set +11'; -- Descricao
        SET @Inventory = @MG_INV;                                                      -- Aloca os bytes hexadecimais do MG
    END

    -- ------------------------------------------------------------------------
    -- 1. CRIACAO DA CONTA NA TABELA MEMB_INFO
    -- Registra o login, senha e configuracoes universais de acesso
    -- ------------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM [dbo].[MEMB_INFO] WHERE memb___id = @AccountID) BEGIN
        INSERT INTO [dbo].[MEMB_INFO] (
            [memb___id], [memb__pwd], [memb_name], [sno__numb],
            [bloc_code], [ctl1_code], [AccountLevel], [AccountExpireDate]
        ) VALUES (
            @AccountID, @Password, @AccountID, '111111111111111111',
            '0', '0', 0, '2050-01-01 00:00:00'
        );
    END

    -- ------------------------------------------------------------------------
    -- 2. VINCULO DO PERSONAGEM NA TABELA AccountCharacter
    -- Registra o personagem @CharName no Slot 1 (GameID1) e selecionado (GameIDC)
    -- ------------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM [dbo].[AccountCharacter] WHERE Id = @AccountID) BEGIN
        INSERT INTO [dbo].[AccountCharacter] (
            [Id], [GameID1], [GameIDC], [MoveCnt], [ExtClass], [Locked]
        ) VALUES (
            @AccountID, @CharName, @CharName, 0, 2, 0
        );
    END ELSE BEGIN
        UPDATE [dbo].[AccountCharacter] SET GameID1 = @CharName, GameIDC = @CharName WHERE Id = @AccountID;
    END

    -- ------------------------------------------------------------------------
    -- 3. CRIACAO COMPLETA DO PERSONAGEM NA TABELA Character
    -- Insere nivel 350, 10 resets, status de atributos, Zen e inventario equipado
    -- ------------------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM [dbo].[Character] WHERE Name = @CharName) BEGIN
        INSERT INTO [dbo].[Character] (
            [AccountID],        -- ID da conta a qual o personagem pertence
            [Name],             -- Nickname do personagem (unico)
            [cLevel],           -- Nivel do personagem (350)
            [LevelUpPoint],     -- Pontos nao distribuidos livres (5.000)
            [Class],            -- Codigo da classe (1=SM, 17=BK, 33=ME, 48=MG)
            [Experience],       -- Pontos de experiencia acumulados (100.000.000)
            [Strength],         -- Atributo de Forca (1.000)
            [Dexterity],        -- Atributo de Agilidade (1.000)
            [Vitality],         -- Atributo de Vitalidade (1.000)
            [Energy],           -- Atributo de Energia (1.000)
            [Inventory],        -- Estrutura binaria do inventario com itens +11
            [Money],            -- Quantidade de Zen no inventario (100.000.000)
            [Life], [MaxLife],  -- Vida Atual e Vida Maxima (1.000 / 1.000)
            [Mana], [MaxMana],  -- Mana Atual e Mana Maxima (1.000 / 1.000)
            [BP], [MaxBP],      -- Stamina/AG Atual e Maxima (500 / 500)
            [MapNumber],        -- Numero do Mapa inicial (0 = Lorencia)
            [MapPosX],          -- Coordenada X inicial no mapa (125)
            [MapPosY],          -- Coordenada Y inicial no mapa (125)
            [MapDir],           -- Direcao inicial de visao do personagem (0)
            [PkCount],          -- Contador de assassinatos/Kills (0)
            [PkLevel],          -- Nivel de PK (3 = Status Amarelo / Normal)
            [PkTime],           -- Tempo restante de penalidade de PK (0)
            [CtlCode],          -- Codigo de Controle do Personagem (0 = Normal, 8 = GM)
            [DbVersion],        -- Versao da estrutura da base de dados (3)
            [ChatLimitTime],    -- Tempo de limite de mute do chat (0)
            [FruitPoint],       -- Pontos de frutos adicionados (0)
            [FruitAddPoint],    -- Pontos adicionais de frutas (0)
            [FruitSubPoint],    -- Pontos subtraidos de frutas (0)
            [ResetCount],       -- Quantidade de resets do personagem (10 Resets)
            [MasterResetCount], -- Quantidade de Master Resets (0)
            [IsNewChar]         -- Indicador de personagem recem-criado (0)
        ) VALUES (
            @AccountID, @CharName, 350, 5000, @Class, 100000000,
            1000, 1000, 1000, 1000,
            @Inventory, 100000000, 1000, 1000, 1000, 1000, 500, 500,
            0, 125, 125, 0, 0, 3, 0,
            0, 3, 0, 0, 0, 0,
            10, 0, 0
        );
    END

    -- Armazena os dados gerados na tabela temporaria do relatorio
    INSERT INTO @ContasCriadas (Num, Login, Senha, NickName, Classe, SetEquipado)
    VALUES (@i, @AccountID, @Password, @CharName, @ClassName, @SetDesc);

    -- Incrementa a variavel contadora do loop WHILE
    SET @i = @i + 1;
END

-- ----------------------------------------------------------------------------
-- EXIBICAO DO RELATORIO FINAL DETALHADO NO SQL SERVER MANAGEMENT STUDIO
-- ----------------------------------------------------------------------------
SELECT 
    Num AS [#], 
    Login AS [Login], 
    Senha AS [Senha], 
    NickName AS [Nick], 
    Classe AS [Classe (Lvl 2)], 
    SetEquipado AS [Itens Equipados (+11)] 
FROM @ContasCriadas;

-- Mensagem de confirmacao no console
PRINT '50 Contas e Personagens Lvl 2 com itens +11 configurados com sucesso!';
GO
